function plant(event) {
    const x = player.x;
    const y = player.y;
    if (tiles[x + ',' + y] && tiles[x + ',' + y].crop === 'seed') {
        tiles[x + ',' + y].stage = 1;
        inventory.seeds--;
        draw();
    }
}

function grow(event) {
    const x = player.x;
    const y = player.y;
    if (tiles[x + ',' + y] && tiles[x + ',' + y].stage === 1) {
        tiles[x + ',' + y].stage = 2;
        draw();
    }
}

function update() {
    day++;
    for (const [key, value] of Object.entries(tiles)) {
        if (value.stage === 2) {
            value.stage = 3;
            inventory.crops++;
        }
    }
    draw();
}

// Increment 3: harvesting.
// h harvests a crop from the player's tile: tiles['x,y'] = { crop, stage: 3 } and crops go up by one.
// Harvesting is done by clicking the 'h' key. If the player's tile has a crop, it is removed from the game and the player's inventory is updated accordingly.
function harvest(event) {
    const x = player.x;
    const y = player.y;
    if (tiles[x + ',' + y] && tiles[x + ',' + y].crop === 'crop') {
        delete tiles[x + ',' + y];
        inventory.crops--;
        draw();
    }
}

// Increment 4: saving and loading.
// s saves the game state to localStorage.
// l loads the game state from localStorage.
function save() {
    localStorage.setItem('gameState', JSON.stringify(game.state()));
}

function load() {
    const gameState = localStorage.getItem('gameState');
    if (gameState) {
        game.state(JSON.parse(gameState));
        draw();
    }
}

document.addEventListener('keydown', movePlayer);
document.addEventListener('keydown', plant);
document.addEventListener('keydown', grow);
document.addEventListener('keydown', harvest);
document.addEventListener('keydown', save);
document.addEventListener('keydown', load);

setInterval(update, 1000); // Increment 5: time-based game progression.
